10	std::complex<double> L0(double x, double y) {
11	  double denom = one - x / y;
12	  if (std::abs(denom) < 1e-7) {
13	    return -cone - cplx1(denom * (half + denom / three));
14	  } else {
15	    return lnrat(x, y) / cplx1(denom);
16	  }
17	}
