28	std::complex<double> L2(double x, double y) {
29	  double r = x / y;
30	  double denom = one - r;
31	  if (std::abs(denom) < 1e-7) {
32	    return (cplx1(10.0) + denom * (cplx1(15.0) + cplx1(18.0) * denom)) /
33	           cplx1(60.0);
34	  } else {
35	    return (lnrat(x, y) - cplx1(half * (r - one / r))) /
36	           std::pow(cplx1(denom), 3);
37	  }
38	}
