94	  return (Ls2(x1, y1, x2, y2) + (L2(x1, y1) + L2(x2, y2)) / 3.0 -
95	          1.0 / (6.0 * r1) - 1.0 / (6.0 * r2)) /
96	         cplx1(one - r1 - r2);
