99	std::complex<double> Lsm1_2mht(double s, double t, double m1sq, double m2sq) {
100	  double r1 = m1sq / t;
101	  double r2 = m2sq / t;
102	  double omr1 = one - r1;
103	  double omr2 = one - r2;
104	  std::complex<double> dilog1, dilog2;
105	
106	  if (omr1 > one) {
107	    dilog1 =
108	        cplx1(pisqo6 - ddilog(r1)) - lnrat(-m1sq, -t) * cplx1(std::log(omr1));
109	  } else {
110	    dilog1 = cplx1(ddilog(omr1));
111	  }
112	
113	  if (omr2 > one) {
114	    dilog2 =
115	        cplx1(pisqo6 - ddilog(r2)) - lnrat(-m2sq, -t) * cplx1(std::log(omr2));
116	  } else {
117	    dilog2 = cplx1(ddilog(omr2));
118	  }
119	
120	  return -dilog1 - dilog2 +
121	         half *
122	             (lnrat(-s, -m1sq) * lnrat(-s, -m2sq) - std::pow(lnrat(-s, -t), 2));
123	}
