9	double I3m1a(double s1, double s2, double s3, double rtmdel) {
10	    using namespace constants_mod;
11	
12	    double d1 = s1 - s2 - s3;
13	    double d2 = s2 - s3 - s1;
14	    double d3 = s3 - s1 - s2;
15	
16	    double arg1 = 2 * std::atan(rtmdel / d1);
17	    double arg2 = 2 * std::atan(rtmdel / d2);
18	    double arg3 = 2 * std::atan(rtmdel / d3);
19	    return 2 / rtmdel * (dclaus(arg1) + dclaus(arg2) + dclaus(arg3));
20	}
21	
22	std::complex<double> I3m1b(double s1, double s2, double s3, double rtdel, double flag) {
23	    using namespace constants_mod;
24	
25	    std::complex<double> result;
26	    double d3 = s3 - s1 - s2;
27	    double x = s1 / s3;
28	    double y = s2 / s3;
29	    double rat = 0.5 * (d3 + rtdel) / s3;
30	    
31	    if (std::abs(rat) < 1.e-3) rat = 2.0 * s1 * s2 / (s3 * (d3 - rtdel));
32	    double rho = 1.0 / rat;
33	    double argx = rho * x;
34	    double argy = rho * y;
35	    double argdlx = -argx;
36	    double argdly = -argy;
37	
38	    if ((argdlx > 1.0) || (argdly > 1.0)) {
39	        std::cerr << "Problems with call of I3m1b" << std::endl;
40	        std::cerr << "argdlx: " << argdlx << std::endl;
41	        std::cerr << "argdly: " << argdly << std::endl;
42	        std::exit(1);
43	    }
44	
45	    double xlog = std::log(std::abs(argx));
46	    double ylog = std::log(std::abs(argy));
47	    double temp = xlog * ylog + pisq / 3.0 + (ylog - xlog) * std::log((1.0 + argy) / (1.0 + argx)) +
48	                 2 * (ddilog(argdlx) + ddilog(argdly));
49	    result = cplx1(temp - std::abs(flag) * pisq) + impi * cplx1(flag * (xlog + ylog));
50	    return -result / cplx1(rtdel);
51	}
52	
53	std::complex<double> i3m(double s1, double s2, double s3) {
54	    using namespace constants_mod;
55	
56	    std::complex<double> result;
57	    double smax = std::max({s1, s2, s3});
58	    double smin = std::min({s1, s2, s3});
59	    double smid = s1 + s2 + s3 - smax - smin;
60	    double del3 = s1 * s1 + s2 * s2 + s3 * s3 - 2 * (s1 * s2 + s2 * s3 + s3 * s1);
61	    double rtdel3;
62	
63	    if (del3 > 0) {
64	        rtdel3 = std::sqrt(del3);
65	        double flag = 0.0;
66	        if (smax < 0) {
67	            result = I3m1b(smax, smid, smin, rtdel3, flag);
68	        } else if (smin > 0) {
69	            result = -I3m1b(-smin, -smid, -smax, rtdel3, flag);
70	        } else if ((smid < 0) && (smin < 0)) {
71	            flag = 1.0;
72	            result = I3m1b(smin, smid, smax, rtdel3, flag);
73	        } else if ((smax > 0) && (smid > 0)) {
74	            flag = -1.0;
75	            result = -I3m1b(-smax, -smid, -smin, rtdel3, flag);
76	        }
77	    } else if (del3 < 0) {
78	        double rtdel3 = std::sqrt(-del3);
79	        if (smax < 0) {
80	            result = std::complex<double>(I3m1a(s1, s2, s3, rtdel3));
81	        } else if (smin > 0) {
82	            result = -std::complex<double>(I3m1a(-s1, -s2, -s3, rtdel3));
83	        }
84	    }
85	
86	    return result;
87	}
