15	static std::complex<double> FFPPcc1(int j1, int j2, int j3, int j4, int j5, int j6, FArray2D<std::complex<double>>& za, FArray2D<std::complex<double>>& zb) {
16	  auto zab = [&za, &zb](int j1, int j2, int j3) {
17	    return za(j1, j2) * zb(j2, j3);
18	  };
19	
20	  std::complex<double> FFPPcc1_value;
21	  FFPPcc1_value =
22	      ((-2.0) * za(j5, j2) * zab(j5, j4, j3))
23	        / (za(j3, j4) * za(j4, j1) * za(j5, j6));
24	
25	  return FFPPcc1_value;
26	}
