30	static std::complex<double> FFPPcc2(int j1, int j2, int j3, int j4, int j5, int j6, FArray2D<std::complex<double>>& za, FArray2D<std::complex<double>>& zb) {
31	  auto zab2 = [&za, &zb](int j1, int j2, int j3, int j4) {
32	    return (za(j1, j2) * zb(j2, j4)) + (za(j1, j3) * zb(j3, j4));
33	  };
34	
35	  std::complex<double> FFPPcc2_value;
36	  FFPPcc2_value =
37	      (2.0 * za(j2, j5) * za(j1, j5) * zab2(j2, j3, j4, j1))
38	        / (za(j2, j3) * za(j3, j4) * za(j4, j1) * za(j5, j6));
39	
40	  return FFPPcc2_value;
41	}
