44	// Eq10.4
45	std::complex<double> FFPPcc(int j1, int j2, int j3, int j4, int j5, int j6, FArray2D<std::complex<double>>& za, FArray2D<std::complex<double>>& zb) {
46	  double s123 = t(j1, j2, j3);
47	  double s234 = t(j2, j3, j4);
48	
49	  std::complex<double> FFPPcc_value;
50	  FFPPcc_value =
51	      (za(j2, j5) * ((za(j1, j2) * za(j4, j5)) - (za(j2, j4) * za(j1, j5))))
52	        / (za(j2, j3) * za(j3, j4) * std::pow(za(j4, j1), 2) * za(j5, j6))
53	        * Lsm1_2me(s123, s234, s(j2, j3), s(j5, j6))
54	
55	      + (za(j2, j5) * ((za(j2, j3) * za(j1, j5)) - (za(j1, j2) * za(j3, j5))))
56	        / (za(j2, j3) * za(j3, j4) * za(j4, j1) * za(j1, j3) * za(j5, j6))
57	        * Lsm1((-s(j1, j2)), (-s123), (-s(j2, j3)), (-s123))
58	
59	      - (za(j2, j5) * ((za(j2, j3) * za(j4, j5)) + (za(j2, j4) * za(j3, j5))))
60	        / (za(j2, j3) * std::pow(za(j3, j4), 2) * za(j4, j1) * za(j5, j6))
61	        * Lsm1_2me(t(j1, j2, j4), s123, s(j1, j2), s(j5, j6))
62	
63	      - std::pow(za(j5, j2), 2)
64	        / (za(j2, j3) * za(j3, j4) * za(j4, j1) * za(j5, j6))
65	        * (Lsm1((-s(j1, j4)), (-t(j1, j2, j4)), (-s(j1, j2)), (-t(j1, j2, j4)))
66	          + Lsm1_2me(t(j1, j3, j4), t(j1, j2, j4), s(j1, j4), s(j5, j6)))
67	
68	      + (FFPPcc1(j1, j2, j3, j4, j5, j6, za, zb) * L0((-s234), (-s(j2, j3))))
69	        / s(j2, j3)
70	      + (FFPPcc2(j1, j2, j3, j4, j5, j6, za, zb) * L0((-s234), (-s(j5, j6))))
71	        / s(j5, j6);
72	
73	  return FFPPcc_value;
74	}
